export const autoRefreshFields = async (
  storageKey: string,
  customFields: any,
  params: string,
  isDateFormater,
  getBusinessFields: Function,
  getBusinessFieldsLatestVersion: Function
) => {
  // if exist in session, use session's directly
  const { getLocalStorage, getSessionStorage, storeData } = CommonUtil;
  if (getSessionStorage().getItem(storageKey)) {
    const sessionFields: any = JSON.parse(
      getSessionStorage().getItem(storageKey) as string
    );
    const fields = mergeFields(sessionFields, customFields, isDateFormater);

    if (fields.length === 0) {
      triggerError(FIELDS_CONFIG_NOT_AVAILABLE);
    }

    return fields;
  } else if (getLocalStorage().getItem(storageKey)) {
    // if exist in localstorage, check active version, if valid, use local's directly, and put in session, otherwise get the latest version and restore it.
    const localFields: any = JSON.parse(
      getLocalStorage().getItem(storageKey) as string
    );
    try {
      // if fields version respond successfully
      const versionRes: any = await getBusinessFieldsLatestVersion();
      if (
        localFields.version.fieldsConfig ===
          versionRes.ratan_suppression_fields_config.activedVersion &&
        localFields.version.fields ===
          versionRes.ratan_suppression_fields.activedVersion
      ) {
        getSessionStorage().setItem(
          storageKey,
          getLocalStorage().getItem(storageKey) as string
        );
        return mergeFields(localFields, customFields, isDateFormater);
      }
    } catch (error) {
      // if response failed, still use data in localstorage
      message.error(
        "Unable to fetch latest field list from server, use local cache instead."
      );
      getSessionStorage().setItem(
        storageKey,
        getLocalStorage().getItem(storageKey) as string
      );
      return mergeFields(localFields, customFields, isDateFormater);
    }
  }

  // else get from back-end
  const res: any = await getBusinessFields(params);
  sortAsAlphabeticalOrder(res.fields);
  storeData(storageKey, JSON.stringify(res));
  getSessionStorage().setItem(storageKey, JSON.stringify(res));

  return mergeFields(res, customFields, isDateFormater);
};

function filterDisabledFields(fields: any, flag) {
  return fields.filter((item) => {
    const scope = JSON.parse(item.scope);
    return !scope.disabledBlotter.includes(flag);
  });
}

export const queryGraphql = (
  url: string,
  query: any,
  setErrorField?: boolean,
  headers = {}
) => {
  const httpLink = new HttpLink({
    uri: url,
  });

  const authMiddleware = new ApolloLink((operation, forward) => {
    // add the token to the headers
    const hooks = getHooks();
    operation.setContext({
      headers: {
        "Single-UI-Authorization": hooks.store?.token,
        // "Frontend-Version": "mfe",
        ...headers,
      },
    });
    return forward(operation);
  });

  const queryClient = new ApolloClient({
    link: from([authMiddleware, errorLink(url), httpLink]),
    cache: new InMemoryCache({
      addTypename: false,
    }),
    defaultOptions: {
      query: {
        fetchPolicy: "no-cache",
        errorPolicy: "all",
      },
    },
  });

  return queryClient
    .query({ query })
    .then(queryHandler(setErrorField))
    .finally(() => {
      ExtendTokenService(url);
    });
};

export const reconnectionAttempts = new Map<
  string,
  { num: number; updateTime: number }
>();
export const timeout = (url, query, next, error, complete, num) => () => {
  reconnectionAttempts.set(url, { num: num + 1, updateTime: 0 });
  subscribeGraphqlNotification(url, query, next, error, complete);
};
export const onDisconnected = (url, query, next, error, complete) => () => {
  const { num, updateTime } = reconnectionAttempts.get(url) || {
    num: 0,
    updateTime: 0,
  };
  console.info("onDisconnected", url, num, updateTime);
  if (num < 5 && new Date().getTime() - updateTime > 5000) {
    setTimeout(timeout(url, query, next, error, complete, num), num * 1000);
  } else if (num <= 5) {
    reconnectionAttempts.set(url, { num: 6, updateTime: 0 });
    logger.error(`Subscription error, url: ${url}`);
  }
};
export const onConnected = (url) => () => {
  const { num } = reconnectionAttempts.get(url) || { num: 0, updateTime: 0 };
  if (num <= 5) {
    reconnectionAttempts.set(url, {
      num: 0,
      updateTime: new Date().getTime(),
    });
  }
};
export const connectionParams = () => ({
  "Single-UI-Authorization": `${getHooks().store?.token}`,
});
export const nextWrap = (next) => (res: any) => {
  const data = res.data
    ? res.data.onExceptionEvent.payload
    : res.onExceptionEvent.payload;
  logger.info(
    `Receive exception notification: exceptionId: ${data.exceptionId}, exceptionCode: ${data.exceptionCode}`
  );
  next(res);
};
const subscribeGraphqlNotification = (
  url: string,
  query: any,
  next: (value: any) => void,
  error?: (error: any) => void,
  complete?: () => void
) => {
  const wsClient = new SubscriptionClient(`${url}`, {
    timeout: 60000,
    connectionParams,
  });
  const wsLink = new WebSocketLink(wsClient);
  // @ts-ignore
  wsLink.subscriptionClient.onDisconnected(
    onDisconnected(url, query, next, error, complete)
  );
  // @ts-ignore
  wsLink.subscriptionClient.onConnected(onConnected(url));

  const subscriptionClient = new ApolloClient({
    link: from([errorLink(url), wsLink]),
    cache: new InMemoryCache({
      addTypename: false,
    }),
  });

  subscriptionClient
    .subscribe({ fetchPolicy: "no-cache", query })
    .subscribe(nextWrap(next), error, complete);
};

