export class Station {
  isIdle = false;
  monitorDatas: MonitorEvent[] = [];
  sendingAbortController: AbortController | null = null;
  constructor() {
    this.read();
    this.addListener();
  }

  eventHandler(v: EET["event"]) {
    this.monitorDatas.push(new MonitorEvent(v.event, v.payloads));
    this.save();
  }

  addListener() {
    MonitorEventEmitter.on(
      EVENT_EMITTER_KEY_EVENT,
      this.eventHandler.bind(this)
    );
    window.addEventListener("visibilitychange", this.process.bind(this));
    document.body.addEventListener("click", MouseEventCapture);
  }
  removeListener() {
    MonitorEventEmitter.off(EVENT_EMITTER_KEY_EVENT);
    window.removeEventListener("visibilitychange", this.process);
  }

  read() {
    requestIdleCallback(() => {
      const cachedMonitorEvents = readMonitorEvents();
      this.monitorDatas = [...cachedMonitorEvents, ...this.monitorDatas];
    });
  }

  save() {
    requestIdleCallback(() => {
      saveMonitorEvents(this.monitorDatas);
    });
  }

  send() {
    const [sendingStatus, abortController] = smartSender(this.monitorDatas);
    this.sendingAbortController = abortController;
    sendingStatus.then((res) => {
      const succeedEvents = res
        .filter((r) => r.status === "fulfilled")
        .flatMap((r) => (r as PromiseFulfilledResult<MonitorEvent[]>).value);
      const succeedEventIds = new Set(succeedEvents.map((i) => i.id));
      this.monitorDatas = this.monitorDatas.filter(
        (d) => !succeedEventIds.has(d.id)
      );
      this.save();
    });
  }

  abortSend() {
    this.sendingAbortController?.abort();
  }

  process(ev: Event) {
    if (this.isIdle !== checkIfIdle(ev)) {
      this.isIdle = !this.isIdle;
      if (this.isIdle) {
        this.send();
      } else {
        this.abortSend();
      }
    }
  }

  destory() {
    this.removeListener();
  }
}

export const sender = async (
  events: MonitorEvent[],
  serviceConfig: ServiceConfig = defaultServiceConfig,
  signal?: AbortSignal
): Promise<MonitorEvent[]> => {
  const singleUIAuthorization = sessionStorage.getItem("SET_TOKEN");
  if (featureScopedEnabled("PM_Client_SDK_V2_Sender_v2")) {
    try {
      await fetch(serviceConfig.url, {
        method: "post",
        headers: {
          "Content-Type": "application/json",
          "Single-Ui-Authorization": sessionStorage.getItem("SET_TOKEN") + "",
        },
        body: JSON.stringify({
          events: events.map((e) => encode(JSON.stringify(e))),
        }),
        keepalive: true,
        signal,
      });
      return events;
    } catch (error) {
      return [];
    }
  } else {
    const res = await Promise.allSettled(
      events.map((e) =>
        Service.service.post(
          serviceConfig.url,
          {
            ...RatanAnalysis2SingleUIBffAnalyze(v2EventTov1Event(e)),
            singleUIAuthorization,
          },
          {
            signal,
          }
        )
      )
    );
    return events.filter((r, i) => res[i].status === "fulfilled");
  }
};

export const smartSender = (
  events: MonitorEvent[],
  serviceConfig: ServiceConfig = defaultServiceConfig
): [Promise<PromiseSettledResult<MonitorEvent[]>[]>, AbortController] => {
  const controller = new AbortController();
  const groupEvents: MonitorEvent[][] = [];
  for (let i = 0; i < events.length; i += serviceConfig.maxGroupCount) {
    groupEvents.push(events.slice(i, i + serviceConfig.maxGroupCount));
  }
  const res = Promise.allSettled(
    groupEvents.map((group) => sender(group, serviceConfig, controller.signal))
  );
  return [res, controller];
};

